contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function with one parameter to vary (unused amount but required by template)
    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(true);

        // observe owner and balance before
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        // perform the state-changing call as a top-level statement and capture revert via try/catch
        bool reverted;
        c.withdraw{value: 0}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe balance after
        uint balAfter = address(c).balance;

        // General rule:
        // - If this contract is not the recorded Owner then withdraw must have reverted and balance unchanged.
        // - If this contract is the Owner then withdraw must not increase the contract balance and final balance is either 0 (all withdrawn) or unchanged if nothing to withdraw.
        assert(
            (ownerBefore != address(this) && reverted && balAfter == balBefore)
            ||
            (ownerBefore == address(this) && !reverted && balAfter <= balBefore)
        );
    }

    receive() external payable {}
}

